parameters.jsCode:
const body = $input.first().json.body ?? {};

const request = {
  channel: String(body.channel ?? "").trim(),
  agent: String(body.agent ?? "").trim(),
  userId: String(body.userId ?? "").trim(),
  conversationId: String(body.conversationId ?? "").trim(),
  message: String(body.message ?? "").trim(),
};

const errors = [];

if (!request.channel) {
  errors.push("channel é obrigatório");
} else if (!["portal", "whatsapp"].includes(request.channel)) {
  errors.push("channel deve ser portal ou whatsapp");
}

if (!request.agent) {
  errors.push("agent é obrigatório");
} else if (!["universal", "study_planner"].includes(request.agent)) {
  errors.push("agent deve ser universal ou study_planner");
}

if (!request.userId) {
  errors.push("userId é obrigatório");
}

if (!request.conversationId) {
  errors.push("conversationId é obrigatório");
}

if (!request.message) {
  errors.push("message é obrigatória");
} else if (request.message.length > 4000) {
  errors.push("message deve ter no máximo 4000 caracteres");
}

return [
  {
    json: {
      isValid: errors.length === 0,
      errors,
      request,
    },
  },
];

parameters.responseBody:
={{
  {
    ok: false,
    error: {
      code: "INVALID_REQUEST",
