const modelResult = $input.first().json;
const request = $("Validate Input").first().json.request;

const replyText = String(
  modelResult.text ??
  modelResult.output ??
  modelResult.response ??
  ""
).trim();

if (!replyText) {
  throw new Error("O Bedrock não retornou uma resposta textual.");
}

return [
  {
    json: {
      ok: true,
      data: {
        conversationId: request.conversationId,
        messageId: `msg-${Date.now()}`,
        agent: request.agent,
        replyText,
        suggestions: [],
        confirmation: null,
      },
      meta: {
        channel: request.channel,
        mocked: false,
        provider: "amazon-bedrock",
        model: "amazon.nova-micro-v1:0",
        version: "v1",
      },
    },
  },
];

